const nav=document.querySelector('#nav-side'),menu=document.querySelector('.menu');
const progress=document.createElement('div');progress.className='scroll-progress';progress.setAttribute('aria-hidden','true');document.body.prepend(progress);
const paintProgress=()=>{const max=document.documentElement.scrollHeight-innerHeight;progress.style.width=(max>0?scrollY/max*100:0)+'%'};paintProgress();addEventListener('scroll',paintProgress,{passive:true});addEventListener('resize',paintProgress);
if(matchMedia('(pointer:fine)').matches)addEventListener('pointermove',e=>{document.body.style.setProperty('--pointer-x',e.clientX+'px');document.body.style.setProperty('--pointer-y',e.clientY+'px')},{passive:true});
menu?.addEventListener('click',()=>{menu.setAttribute('aria-expanded',String(nav.classList.toggle('open')))});
const groups=[...nav.querySelectorAll('details')];groups.forEach(d=>d.addEventListener('toggle',()=>{if(d.open)groups.forEach(o=>{if(o!==d)o.open=false})}));
document.addEventListener('click',e=>{if(nav&&!nav.contains(e.target)&&e.target!==menu)groups.forEach(d=>d.open=false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const d=groups.find(x=>x.open);if(d){d.open=false;d.querySelector('summary').focus()}nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});
document.querySelectorAll('.folder').forEach(b=>{b.setAttribute('aria-pressed',String(b.classList.contains('active')));b.addEventListener('click',()=>{document.querySelectorAll('.folder').forEach(o=>{o.classList.toggle('active',o===b);o.setAttribute('aria-pressed',String(o===b))});const title=document.querySelector('.hero-copy h2'),copy=document.querySelector('.hero-copy p');if(title)title.textContent=b.dataset.title;if(copy)copy.textContent=b.dataset.copy})});
document.querySelectorAll('.catalog-row').forEach((row,i)=>{const target=['audit','design','prototype','system'][i];row.setAttribute('role','button');row.tabIndex=0;row.setAttribute('aria-expanded',String(row.classList.contains('active')));const p=row.querySelector('p');if(p){const a=document.createElement('a');a.href='services.html#'+target;a.textContent='Lihat program ↗';p.append(document.createElement('br'),a)}const select=()=>{document.querySelectorAll('.catalog-row').forEach(o=>{o.classList.toggle('active',o===row);o.setAttribute('aria-expanded',String(o===row))})};row.addEventListener('click',e=>{if(!e.target.closest('a'))select()});row.addEventListener('keydown',e=>{if(e.target===row&&['Enter',' '].includes(e.key)){e.preventDefault();select()}})});
const filters=[...document.querySelectorAll('.filter')];filters.forEach(b=>{b.removeAttribute('role');b.removeAttribute('aria-selected');b.setAttribute('aria-pressed',String(b.classList.contains('active')));b.addEventListener('click',()=>{filters.forEach(o=>{o.classList.toggle('active',o===b);o.setAttribute('aria-pressed',String(o===b))});document.querySelectorAll('.case').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.category!==b.dataset.filter)})});document.querySelector('.filters')?.setAttribute('role','group');
function routeHash(){const hash=location.hash.slice(1);const b=filters.find(b=>b.dataset.filter===hash);if(b)b.click();const d=document.getElementById(hash);if(d?.matches('.service-folder')){d.open=true;d.scrollIntoView()}}routeHash();addEventListener('hashchange',routeHash);
const current=location.pathname.split('/').pop()||'index.html';document.querySelectorAll('.submenu a').forEach(a=>{if(a.getAttribute('href')?.split('#')[0]===current)a.setAttribute('aria-current','page')});
const observer='IntersectionObserver'in window?new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.12,rootMargin:'0px 0px -5%'}):null;document.querySelectorAll('.reveal').forEach(el=>observer?observer.observe(el):el.classList.add('visible'));
const copy={reflection:['DISCOVER / OBJECTIVE','Memahami tujuan dan pengguna','Menyusun hierarki KPI','Menguji kejelasan visual','Menyiapkan handoff'],elevation:['DEFINE / DESIGN','Memetakan alur keputusan','Memilih bentuk visualisasi','Mendesain states & filters','Membuat prototype'],summary:['DELIVER / HANDOFF','Merangkum temuan utama','Merapikan design system','Menyiapkan spesifikasi build','Review implementasi']};document.querySelectorAll('.transfer').forEach(b=>{b.setAttribute('aria-pressed',String(b.classList.contains('active')));b.addEventListener('click',()=>{document.querySelectorAll('.transfer').forEach(o=>{o.classList.toggle('active',o===b);o.setAttribute('aria-pressed',String(o===b))});const c=copy[b.dataset.panel],d=document.querySelector('.transfer-detail');d.querySelector('h3').textContent=c[0];d.querySelector('ol').replaceChildren(...c.slice(1).map(t=>{const li=document.createElement('li');li.textContent=t;return li}))})});
document.querySelector('#brief-form')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);const text=[...data].map(([k,v])=>k.toUpperCase()+': '+v).join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='dashboard-project-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#brief-status').textContent='Brief berhasil disiapkan untuk diunduh.'});
